// ═══════════════════════════════════════════════════════════════════════════
// Test DB helper — spins up an in-memory Postgres-compatible DB (pg-mem)
// loaded with our schema + a seed clinic. Used by tool unit tests so they
// run without touching the real Railway Postgres.
//
// Key compatibility notes:
//   - pg-mem doesn't ship gen_random_uuid() — we register it as a function
//     that returns a v4 UUID generated by Node's crypto module.
//   - pg-mem has no native CREATE EXTENSION support — we strip that line
//     from the migration SQL before applying. The function we registered
//     replaces pgcrypto's role for our needs.
//   - pg-mem's TIME column returns 'HH:MM:SS' strings, same as real pg.
//
// Usage:
//   const { setupTestDb, seedSaiShradha } = require('./tools/testHelpers/setupDb');
//   const { pool, clinicId, doctorsByName } = await setupTestDb();
// ═══════════════════════════════════════════════════════════════════════════

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { newDb, DataType } = require('pg-mem');

const MIGRATION_FILE = path.join(__dirname, '..', '..', 'db', 'migrations', '001_tool_calling_schema.sql');

function uuidv4() {
  // RFC 4122 v4 — sufficient for tests; pg-mem treats UUID as a string.
  return crypto.randomUUID();
}

// ─── THE ESCAPE HATCH THIS FILE HAS BEEN ADVERTISING ────────────────────────
// skipUnlessSupported prints "Set TEST_DATABASE_URL to a real Postgres to
// restore this coverage" — and nothing read TEST_DATABASE_URL. The variable
// appeared only in that message and in a comment, so the four booking cases had
// no route back and the instruction was a dead end.
//
// With it set, tests run against a REAL Postgres: every capability probe passes,
// nothing skips, and the CTE-feeding-INSERT upsert that is the whole point of
// tools/bookAppointment.js is finally executed.
//
//     docker run -d --name ritu-test-pg -e POSTGRES_PASSWORD=test \
//       -e POSTGRES_DB=ritu_test -p 55432:5432 postgres:16-alpine
//     DATABASE_URL=postgres://postgres:test@127.0.0.1:55432/ritu_test node db/migrate.js
//     TEST_DATABASE_URL=postgres://postgres:test@127.0.0.1:55432/ritu_test npm test
//
// Each run works in its OWN schema, created and dropped around the test, so two
// runs cannot collide and nothing survives to leak into the next one. It must
// never be pointed at a clinic database; the guard below refuses the obvious
// ways that happens by accident.
async function setupRealPostgres(url) {
  if (/railway|rlwy\.net|amazonaws|supabase|neon\.tech/i.test(url)) {
    throw new Error(
      `TEST_DATABASE_URL looks like a managed/production host. Refusing: this helper CREATEs and DROPs schemas.\n` +
      `        Use a local throwaway Postgres (see the comment in tools/testHelpers/setupDb.js).`
    );
  }
  const { Pool } = require('pg');
  const schema = `test_${crypto.randomBytes(6).toString('hex')}`;
  const admin = new Pool({ connectionString: url });
  await admin.query(`CREATE SCHEMA ${schema}`);
  await admin.end();

// SEARCH_PATH ON THE CONNECTION, NOT IN A HANDLER. This was
//     pool.on('connect', (c) => c.query(`SET search_path TO ${schema}`))
// which fires a query on a client the pool may already be using — pg warns
// "client.query() when the client is already executing a query" — and under the
// parallel test runner it lost the race: statements landed outside the schema
// and the run died with `relation "t" does not exist`. It passed every time the
// file was run alone, which is the worst way for a harness to be wrong.
// `options` is sent at connection setup, before any query can be issued.
  const pool = new Pool({ connectionString: url, options: `-c search_path=${schema},public` });

  // EVERY migration, in order — not just 001. The pg-mem path loads 001 alone
  // because that is all the double can parse, and copying that here produced
  // `column "is_walk_in" of relation "appointments" does not exist`: is_walk_in
  // arrives in 005, and 005 is exactly the file the booking upsert depends on.
  // A real-Postgres harness that stops at 001 is a different schema from
  // production wearing production's name.
  //
  // Statements go one at a time via the runner's own splitter, so 005's
  // CREATE INDEX CONCURRENTLY works here for the same reason it now works in
  // db/migrate.js — and so a migration that breaks the schema fails the test
  // suite rather than waiting for a deploy.
  const { splitStatements } = require('../../db/splitStatements');
  const dir = path.join(__dirname, '..', '..', 'db', 'migrations');
// CANONICAL MIGRATIONS ONLY, and tolerate one vanishing mid-read.
// tests/test-migration-no-transaction.js writes a scratch file into the REAL
// db/migrations/ directory — it has to, because it tests the checker that scans
// that directory — and deletes it again. Under the parallel runner that raced
// with every other test enumerating the same folder, which surfaced as
// `ENOENT: 999_test_tmp.sql` or `relation "t" does not exist` on whichever test
// happened to read at the wrong moment. Intermittent, and never when the file
// was run alone.
//   · NNN must be 0-prefixed: the scratch file is deliberately 999_.
//   · readFileSync is guarded: readdir and read are not one atomic act.
  for (const f of fs.readdirSync(dir).filter((x) => /^0\d\d_.*\.sql$/.test(x)).sort()) {
    let raw;
    try { raw = fs.readFileSync(path.join(dir, f), 'utf-8'); } catch (_) { continue; }
    const sql = raw.replace(/^\s*DROP TABLE[^;]*;\s*$/gm, '');
    for (const stmt of splitStatements(sql)) {
      try {
        await pool.query(stmt);
      } catch (e) {
        throw new Error(`migration ${f} failed in the test harness: ${e.message}\n  statement: ${stmt.replace(/\s+/g, ' ').slice(0, 120)}`);
      }
    }
  }

  // Real Postgres does all of it — that is the point.
  pool.supports = { cteInsert: true, realPostgres: true };
  const end = pool.end.bind(pool);
  pool.end = async () => {
    try {
      const a = new Pool({ connectionString: url });
      await a.query(`DROP SCHEMA IF EXISTS ${schema} CASCADE`);
      await a.end();
    } catch (_) { /* the schema outliving a crashed run is not worth failing on */ }
    return end();
  };
  return pool;
}

async function setupTestDb() {
  if (process.env.TEST_DATABASE_URL) {
    const pool = await setupRealPostgres(process.env.TEST_DATABASE_URL);
    return seedInto(pool);
  }
  const db = newDb({ autoCreateForeignKeyIndices: true });

  // Provide gen_random_uuid() — pgcrypto isn't available in pg-mem.
  // `impure: true` disables pg-mem's per-statement memoization so each row
  // gets a freshly generated UUID instead of all rows sharing one value.
  db.public.registerFunction({
    name: 'gen_random_uuid',
    returns: DataType.uuid,
    impure: true,
    implementation: () => uuidv4()
  });
  // Some queries may use NOW() — pg-mem supports it natively.

  // jsonb_array_length(): production uses it to ask "is this a substantive
  // call?" — calls.transcript with at least N turns — and pg-mem implements
  // very few native functions. Without it the double throws where real
  // Postgres answers, which makes a green pg-mem run mean less than it should:
  // the whole point of the double is that a test passing on it is evidence.
  // Registered rather than avoided, because rewriting production SQL to suit
  // the test double is how the double stops resembling production.
  db.public.registerFunction({
    name: 'jsonb_array_length',
    args: [DataType.jsonb],
    returns: DataType.integer,
    implementation: (v) => {
      const j = typeof v === 'string' ? JSON.parse(v) : v;
      if (!Array.isArray(j)) throw new Error('cannot get array length of a non-array');
      return j.length;
    },
  });

  // Load + sanitize the migration SQL.
  let sql = fs.readFileSync(MIGRATION_FILE, 'utf-8');
  // pg-mem doesn't implement CREATE EXTENSION; drop those lines.
  sql = sql.replace(/^\s*CREATE EXTENSION[^;]*;\s*$/gm, '');
  // pg-mem doesn't implement DROP TABLE IF EXISTS … CASCADE the same way,
  // and we're starting from a blank DB anyway. Strip the drops.
  sql = sql.replace(/^\s*DROP TABLE[^;]*;\s*$/gm, '');

  db.public.none(sql);

  // ─── THE LATER MIGRATIONS, AS FAR AS THE DOUBLE CAN FOLLOW ────────────────
  // This harness loaded migration 001 ONLY, because that is all pg-mem could
  // parse when it was written. That was survivable while nothing in db.js
  // depended on a later column — and it stopped being survivable the moment one
  // did: migration 010 added patients.name_latin, patientIdentity started
  // writing it, and every pg-mem test driving upsertPatient failed with
  // `column "name_latin" does not exist`. The double had quietly become a
  // different schema wearing production's name.
  //
  // So: attempt every migration, statement by statement, and keep the ones the
  // double can take. Simple ALTERs and indexes go through; the CTE-and-DO-block
  // shapes pg-mem cannot parse are skipped and COUNTED. Skipping silently is
  // what created this gap, so the count is published on pool.supports and the
  // capability probe below still gates the tests that genuinely cannot run.
  const { splitStatements } = require('../../db/splitStatements');
  const laterDir = path.join(__dirname, '..', '..', 'db', 'migrations');
  const skipped = [];
  for (const f of fs.readdirSync(laterDir).filter((x) => /^0\d\d_.*\.sql$/.test(x)).sort()) {
    if (f.startsWith('001_')) continue;            // already loaded above
    let raw;
    try { raw = fs.readFileSync(path.join(laterDir, f), 'utf-8'); } catch (_) { continue; }
    for (const stmt of splitStatements(raw.replace(/^\s*(DROP TABLE|CREATE EXTENSION)[^;]*;\s*$/gm, ''))) {
      try { db.public.none(stmt); }
      catch (e) { skipped.push(`${f}: ${stmt.replace(/\s+/g, ' ').slice(0, 60)} — ${e.message.slice(0, 60)}`); }
    }
  }

  const adapters = db.adapters.createPg();
  const { Pool } = adapters;
  const pool = new Pool();

  // ─── WHAT THIS DOUBLE CANNOT DO, STATED RATHER THAN DISCOVERED ─────────────
  // pg-mem parses `WITH x AS (…) SELECT` but NOT a CTE feeding an INSERT, which
  // is the shape of the idempotent booking upsert in tools/bookAppointment.js
  // (`WITH prev AS (…) INSERT … ON CONFLICT … DO UPDATE`, landed 300b8c1). Four
  // booking tests therefore died on a parse error rather than an assertion, and
  // stayed red long enough that nobody read the suite tail — I reported "all
  // green" twice today from runs that never reached them.
  //
  // Three ways to make them green, and two are worse than red:
  //   · rewrite the production query to suit the double — changing a
  //     correctness-critical booking upsert to please a test is backwards
  //   · intercept the query in this harness and hand back a canned result —
  //     that is a green tick over code nobody ran, which is the exact failure
  //     this repo spent today unlearning
  // So: probe the capability, publish it, and let the tests skip the cases they
  // genuinely cannot cover while still running everything else.
  //
  // Real Postgres (TEST_DATABASE_URL) would cover all of it. Until then the
  // gap is named, not hidden.
  let cteInsert = true;
  try {
    db.public.none('CREATE TABLE __probe (id int)');
    db.public.none('WITH s AS (SELECT 1 AS v) INSERT INTO __probe (id) SELECT v FROM s');
    db.public.none('DROP TABLE __probe');
  } catch (_) { cteInsert = false; }
  // migrationsSkipped names what the double could not take, so a test that
  // needs one of those columns fails with a reason rather than a mystery.
  pool.supports = { cteInsert, migrationsSkipped: skipped };
  if (skipped.length && process.env.VERBOSE_TEST_DB) {
    console.log(`  [setupDb] pg-mem could not apply ${skipped.length} statement(s):`);
    skipped.forEach((x) => console.log(`    ${x}`));
  }

  return seedInto(pool, db);
}

// One clinic, whichever backend the pool is. Shared so the pg-mem and real
// Postgres paths cannot seed differently and quietly test different worlds.
async function seedInto(pool, db = null) {
  const { rows: [clinic] } = await pool.query(
    `INSERT INTO clinics (name, timezone) VALUES ('Sai Shradha Health Care Centre', 'Asia/Kolkata') RETURNING id`
  );
  return { db, pool, clinicId: clinic.id };
}

// Seed the same doctor roster as db/seed-sai-shradha.js but into a pg-mem
// instance. Returns a map { 'Dr. Vikas Gaikwad' → row, … } for tests to
// reference by name.
async function seedSaiShradha(pool, clinicId) {
  const doctors = [
    {
      name: 'Dr. Vikas Gaikwad', specialty: 'General', is_on_call: false, fee_inr: null,
      notes: 'Director — available all 7 days.',
      schedules: [0, 1, 2, 3, 4, 5, 6].map(d => ({ day_of_week: d, start_time: '15:00', end_time: '18:00', is_walk_in: false }))
    },
    {
      name: 'Dr. Sunil Nikam', specialty: 'Orthopedic', is_on_call: false, fee_inr: 500,
      notes: 'Walk-in only on Tue/Thu/Sat. Placeholder hours; actual is OT-dependent.',
      schedules: [
        { day_of_week: 2, start_time: '10:00', end_time: '13:00', is_walk_in: true, notes: 'Walk-in' },
        { day_of_week: 4, start_time: '10:00', end_time: '13:00', is_walk_in: true, notes: 'Walk-in' },
        { day_of_week: 6, start_time: '10:00', end_time: '13:00', is_walk_in: true, notes: 'Walk-in' }
      ]
    },
    {
      name: 'Dr. Priyanka Bhosale', specialty: 'Gynecology', is_on_call: false, fee_inr: 700,
      notes: null,
      schedules: [1, 2, 3, 4, 5].map(d => ({ day_of_week: d, start_time: '15:00', end_time: '16:30', is_walk_in: false }))
    },
    {
      name: 'Dr. Kapil Patwardhan', specialty: 'Internal Medicine', is_on_call: false, fee_inr: 800,
      notes: null,
      schedules: [1, 2, 3, 4, 5].map(d => ({ day_of_week: d, start_time: '18:30', end_time: '20:30', is_walk_in: false }))
    },
    { name: 'Dr. TBD',              specialty: 'Neurologist',  is_on_call: true, fee_inr: null, notes: 'On-call' },
    { name: 'On-call Nephrologist', specialty: 'Nephrologist', is_on_call: true, fee_inr: null, notes: 'On-call' },
    { name: 'On-call Urologist',    specialty: 'Urology',      is_on_call: true, fee_inr: null, notes: 'On-call' },
    { name: 'On-call Pediatrician', specialty: 'Pediatric',    is_on_call: true, fee_inr: null, notes: 'On-call' },
    { name: 'On-call Anesthetist',  specialty: 'Anesthesia',   is_on_call: true, fee_inr: null, notes: 'On-call' },
    { name: 'On-call Surgeon',      specialty: 'Surgery',      is_on_call: true, fee_inr: null, notes: 'On-call' }
  ];

  const byName = {};
  for (const doc of doctors) {
    const { rows: [d] } = await pool.query(
      `INSERT INTO doctors (clinic_id, name, specialty, is_on_call, fee_inr, notes)
       VALUES ($1, $2, $3, $4, $5, $6) RETURNING id, name, specialty, fee_inr, is_on_call`,
      [clinicId, doc.name, doc.specialty, doc.is_on_call, doc.fee_inr, doc.notes]
    );
    byName[doc.name] = d;
    for (const s of doc.schedules || []) {
      await pool.query(
        `INSERT INTO doctor_schedules (doctor_id, day_of_week, start_time, end_time, is_walk_in, notes)
         VALUES ($1, $2, $3, $4, $5, $6)`,
        [d.id, s.day_of_week, s.start_time, s.end_time, s.is_walk_in || false, s.notes || null]
      );
    }
  }
  return byName;
}

// Skip a whole file when the double cannot run the code under test, and say
// exactly what stopped being covered. A SKIP that does not name its gap is a
// green tick with a hole behind it.
function skipUnlessSupported(pool, capability, whatIsLost) {
  if (pool && pool.supports && pool.supports[capability]) return;
  console.log(`\n⏭  SKIP — the pg-mem test double cannot run this file's code path (${capability}).`);
  console.log(`   NOT COVERED: ${whatIsLost}`);
  console.log('   pg-mem parses `WITH x AS (…) SELECT` but not a CTE feeding an INSERT, which is');
  console.log('   the shape of the idempotent booking upsert (tools/bookAppointment.js, 300b8c1).');
  console.log('   Set TEST_DATABASE_URL to a real Postgres to restore this coverage.');
  process.exit(0);
}

module.exports = { setupTestDb, seedSaiShradha, skipUnlessSupported };
